    /// `has_tool_calls` must not leak into `Failed`/`Cancelled`/etc.
    #[test]
    fn terminal_events_failed_status_ignores_has_tool_calls() {
        let events = terminal_events(Some(usage()), Status::Failed, None, true);
        assert!(
            matches!(
